opener(6, 'השקעות מוחזקות למסחר', 'שאלת החלק: מה מציגים במאזן, ומה עובר לרווח והפסד?',
       ['שווי בבורסה בכל תאריך מאזן', 'שינוי בשווי, דיבידנד וריבית', 'מכירה: רווח ביחס לשווי האחרון', 'מסבירים יחד ונסו לבד'], 25)

S('s-tdef', 'השקעות למסחר', 'השקעות למסחר: מה שהבורסה אומרת',
  '<div class="row eq2 top">'
  + DEF('השקעות למסחר', 'עודפי מזומנים שהושקעו לטווח קצר מאוד בניירות ערך הנסחרים בבורסה. נכס שוטף.', 'החברה קנתה מניות ב-40,000 ש״ח כדי למכור אותן בתוך כמה חודשים.', trm='trade')
  + DEF('מדידה לפי שווי', 'בכל תאריך מאזן מציגים את השווי בבורסה. עלייה בשווי היא רווח, וירידה היא הפסד, בדוח רווח והפסד של אותה שנה.', 'שווה היום 48,000 ש״ח: מציגים 48,000 ש״ח, ורווח של 8,000 ש״ח.', 1, trm='fv') + '</div>'
  + '<div class="row eq2 top mt">'
  + DEF('דיבידנד וריבית', 'מה שההשקעה משלמת לנו. הכנסה בדוח רווח והפסד, בנוסף לשינוי בשווי.', 'קיבלנו דיבידנד של 2,700 ש״ח: הכנסה של 2,700 ש״ח.', 2, trm='divinc')
  + DEF('רווח או הפסד במכירה', 'התמורה, פחות <b>השווי האחרון שהוצג</b>. לא פחות העלות המקורית: מה שהיה עד אז כבר נרשם.', 'הוצגה ב-52,000 ש״ח, נמכרה ב-49,500 ש״ח: הפסד של 2,500 ש״ח.', 3, trm='gainsale') + '</div>', kick='חלק 6 · הגדרה והדגמה')

TZ = [('1.1.2024', 40000), ('31.12.2024', 48000), ('31.12.2025', 46000), ('31.12.2026', 52000, 'ודיבידנד 2,700'), ('1.2.2027', 49500, 'מכירה')]
S('s-tline', 'השווי לאורך הזמן', 'צחי פ. בע״מ: השווי לאורך הזמן, ומה עובר לרווח והפסד',
  ILLW(VLINE(TZ, 1))
  + BAND('dg', 'כל שנה עומדת לעצמה: הרווח או ההפסד הוא השינוי מן השווי <b>הקודם</b>, לא מן העלות. ההפסד במכירה, 2,500 ש״ח, נמדד מ-52,000 ש״ח.', 6)
  + PUN('הבורסה עולה? רווח. יורדת? הפסד. ככה כל דצמבר.', 7), kick='חלק 6 · תמונה')

